sksl:
#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
uniform float amzp_speed;
uniform float amzp_evolution;
uniform float amzp_seed;
uniform float amzp_strength;
uniform float amzp_amp;
uniform float amzp_cutoff;
uniform float amzp_lumaNoise;
uniform float amzp_chromaNoise;
uniform float amzp_hueNoise;
uniform float amzp_chromaLoss;
uniform float amzp_sharpen;
uniform float amzp_dotCrawl;
uniform float amzp_headSwitch;
uniform float amzp_lmOn;
uniform float amzp_lmFreq;
uniform float amzp_lmPhase;
uniform float amzp_lmLight;
uniform float amzp_lmQuant;
uniform float amzp_teOn;
uniform float amzp_teStart;
uniform float amzp_teEnd;
uniform float amzp_teProb;
uniform float amzp_teFade;
uniform float amzp_teGamma;
uniform float amzp_snow;
uniform float amzp_interference;
uniform float amzp_tracking;
uniform float amzp_jitter;
uniform float amzp_roll;
uniform float amzp_bleed;
uniform float amzp_chroma;
uniform float amzp_saturation;
uniform float amzp_ghost;
uniform float amzp_ghostOffset;
uniform float amzp_scanlines;
uniform float amzp_lineSize;
uniform float amzp_vignette;
uniform float amzp_overdrawOn;
uniform float amzp_quality;
    float qTaps() { return amzp_quality < 1.5 ? 5.0 : (amzp_quality < 2.5 ? 7.0 : (amzp_quality < 3.5 ? 9.0 : (amzp_quality < 4.5 ? 11.0 : 13.0))); }
    float2 l2s(float2 v) { return (float4(v, 0.0, 1.0) * amzLayerToScreen()).xy; }
    float h1(float x) { return fract(sin(x * 91.3458 + amzp_seed * 13.17) * 47453.5453); }
    float h2(float2 p) { return fract(sin(dot(p, float2(12.9898, 78.233)) + amzp_seed * 7.31) * 43758.5453); }
    float vn(float x) { float i = floor(x), f = fract(x); return mix(h1(i), h1(i + 1.0), f * f * (3.0 - 2.0 * f)); }
    float vx(float xr, float cell, float line, float salt) {
        float p = xr / cell;
        float i = floor(p), f = fract(p);
        f = f * f * (3.0 - 2.0 * f);
        return mix(h2(float2(i, line + salt)), h2(float2(i + 1.0, line + salt)), f);
    }
    float vn2(float2 p, float salt) {
        float2 i = floor(p), f = fract(p);
        f = f * f * (3.0 - 2.0 * f);
        float a = h2(i + float2(0.0, salt)), b = h2(i + float2(1.0, salt));
        float c = h2(i + float2(0.0, 1.0 + salt)), d = h2(i + float2(1.0, 1.0 + salt));
        return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
    }
    float4 src(float2 uv) {
        uv.x = clamp(uv.x, 0.0, 1.0);
        if (uv.y < 0.0 || uv.y > 1.0) return float4(0.0);
        return amzTexture(0, l2s(uv));
    }
    float3 toYIQ(float3 c) { return float3(dot(c, float3(0.299, 0.587, 0.114)), dot(c, float3(0.596, -0.274, -0.322)), dot(c, float3(0.211, -0.523, 0.312))); }
    float3 toRGB(float3 y) { return float3(y.x + 0.956 * y.y + 0.621 * y.z, y.x - 0.272 * y.y - 0.647 * y.z, y.x - 1.106 * y.y + 1.703 * y.z); }
    float3 unp(float4 c) { return c.a > 0.0001 ? c.rgb / c.a : float3(0.0); }
    void nmMain() {
        float2 W = layer;
        float S = amzp_strength / 40.0;
        float t = time * amzp_speed + amzp_evolution;
        float2 uv = amzLayerNorm();
        float y = 1.0 - uv.y;
        float lh = max(amzp_lineSize, 1.0);
        float line = floor(y * W.y / lh);
        float fr = floor(t * 24.0);
        float xr = uv.x * 540.0;
        float rollOff = 0.0;
        if (amzp_roll > 0.0) rollOff = fract(t * amzp_roll * 0.35);
        float yr = fract(y + rollOff);
        float seam = amzp_roll > 0.0 ? smoothstep(0.0, 0.03, yr) * smoothstep(1.0, 0.97, yr) : 1.0;
        uv.y = 1.0 - yr;
        y = yr;
        float dx = (h2(float2(line, fr)) - 0.5) * 2.0 * amzp_jitter;
        float band = fract(t * 0.11 + h1(3.0));
        float bd = (y - band) / 0.08;
        float trk = amzp_tracking * exp(-bd * bd);
        dx += trk * (vn(y * 180.0 + t * 30.0) - 0.5) * 220.0 + trk * 25.0;
        dx += amzp_tracking * 6.0 * sin(y * 25.0 + t * 3.0) * (vn(t * 0.7) - 0.3);
        uv.x += dx / W.x;
        float hb = 0.045;
        float inHead = (amzp_headSwitch > 0.0 && y > 1.0 - hb) ? 1.0 : 0.0;
        float hd = clamp((y - (1.0 - hb)) / hb, 0.0, 1.0);
        uv.x += inHead * amzp_headSwitch * S * (vx(hd * 40.0, 3.0, fr, 71.0) - 0.5) * 0.12 * hd;
        float sigL = (0.3 + (100.0 - amzp_cutoff) * 0.4) * min(S, 3.0);
        float nt = qTaps();
        float half_ = (nt - 1.0) * 0.5;
        float stepU = 4.4 / (nt - 1.0);
        float yL1 = 0.0, yL2 = 0.0, w1 = 0.0, w2 = 0.0;
        for (int i = 0; i < 13; i++) {
            if (float(i) >= nt) break;
            float u = (float(i) - half_) * stepU;
            float4 s = src(uv + float2(u * sigL / 540.0, 0.0));
            float yy = dot(unp(s), float3(0.299, 0.587, 0.114));
            float g1 = exp(-0.5 * u * u);
            float g2 = exp(-0.125 * u * u);
            yL1 += yy * g1; w1 += g1;
            yL2 += yy * g2; w2 += g2;
        }
        yL1 /= w1; yL2 /= w2;
        float Y = yL1 + amzp_sharpen * 1.2 * (yL1 - yL2);
        float sigC = (sigL * 2.2 + 2.0 + amzp_bleed * 0.35 + amzp_chromaLoss * 6.0 * S) * (S > 0.0 ? 1.0 : 0.0);
        float2 ch = float2(0.0);
        float tot = 0.0;
        for (int i = 0; i < 13; i++) {
            if (float(i) >= nt) break;
            float u = (float(i) - half_) * stepU;
            float4 s = src(uv + float2((u * sigC + amzp_chroma) / 540.0, 0.0));
            float g = exp(-0.5 * u * u);
            ch += toYIQ(unp(s)).yz * g;
            tot += g;
        }
        ch /= tot;
        float4 c0 = src(uv);
        float a = c0.a;
        ch *= (1.0 - amzp_chromaLoss * min(S, 1.0)) * amzp_saturation;
        float ln = amzp_lumaNoise * S;
        float cn = amzp_chromaNoise * S;
        float nL = (vn2(float2(xr / 11.0, y * W.y / (lh * 1.5)), fr * 37.0) - 0.5) * 2.0;
        Y += ln * 0.04 * nL;
        float cI = (h2(float2(line, fr * 3.1 + 11.0)) - 0.5) * 2.0 * 0.7 + (vx(xr, 90.0, line, fr * 5.3 + 3.0) - 0.5) * 2.0 * 0.9;
        float cQ = (h2(float2(line, fr * 2.3 + 29.0)) - 0.5) * 2.0 * 0.7 + (vx(xr, 90.0, line, fr * 4.7 + 9.0) - 0.5) * 2.0 * 0.9;
        ch += cn * float2(0.034 * cI, 0.0155 * cQ);
        float ang = radians(amzp_hueNoise) * S * ((h2(float2(line, fr * 1.7 + 53.0)) - 0.5) * 2.0 + (vx(xr, 60.0, line, fr * 2.9 + 41.0) - 0.5) * 2.0);
        float ca = cos(ang), sa = sin(ang);
        ch = float2(ch.x * ca - ch.y * sa, ch.x * sa + ch.y * ca);
        float ph = 6.2831853 * (xr / 8.0 + line * 0.25 + fr * 0.5);
        Y += amzp_dotCrawl * S * 0.12 * (length(ch) + 0.02) * sin(ph);
        if ((amzp_lmOn>0.5)) {
            float mph = 6.2831853 * (Y * (1.0 + amzp_lmFreq * 9.0) + amzp_lmPhase * 0.1);
            float m = sin(mph);
            if (amzp_lmQuant >= 1.0) { float q = floor(amzp_lmQuant + 0.5); m = floor(m * q + 0.5) / q; }
            Y += amzp_lmLight * 0.32 * (m + 0.55);
            ch *= 1.0 + amzp_lmLight * 0.6;
            if ((amzp_teOn>0.5) && amzp_teProb > 0.0) {
                float lnE = floor(y * W.y / max(lh * 0.67, 1.0));
                if (h2(float2(lnE, fr * 1.13 + 401.0)) < amzp_teProb) {
                    float x0 = h2(float2(lnE, fr * 0.71 + 77.0)) * 1.1 - 0.1;
                    float len = max(amzp_teFade, 0.001) * 0.05 * (0.4 + 1.2 * h2(float2(lnE, fr + 9.0)));
                    float u = (uv.x - x0) / len;
                    if (u >= 0.0 && u <= 1.0) {
                        float k = pow(1.0 - u, max(amzp_teGamma, 0.01)) * smoothstep(0.0, 0.03, u);
                        Y += mix(amzp_teStart, amzp_teEnd, u) * k * 0.85;
                    }
                }
            }
        }
        Y = (Y - 0.5) * amzp_amp + 0.5;
        float3 yiq = float3(Y, ch);
        if (amzp_ghost > 0.0) {
            float4 g = src(uv - float2(amzp_ghostOffset / W.x, 0.0));
            yiq.x = mix(yiq.x, yiq.x * 0.85 + toYIQ(unp(g)).x * 0.35, amzp_ghost);
            a = max(a, g.a * amzp_ghost * 0.5);
        }
        float3 col = toRGB(yiq);
        if (inHead > 0.5) {
            float sp = h2(floor(float2(xr * 0.5, line)) + fr * 1.91);
            float dens = amzp_headSwitch * S * (0.12 + 0.35 * hd);
            col *= 1.0 - 0.45 * amzp_headSwitch * min(S, 1.0) * hd;
            col = mix(col, float3(sp > 0.5 ? 1.0 : 0.0), clamp(dens * step(0.3, h2(float2(floor(xr * 0.125), line + fr))), 0.0, 1.0));
        }
        float bars = sin((y * 3.0 - t * 0.9) * 6.2831853) * 0.5 + 0.5;
        float moire = sin(y * W.y * 0.9 + uv.x * 40.0 + t * 40.0) * 0.5 + 0.5;
        col += amzp_interference * (bars * 0.12 + moire * 0.06 * bars);
        float nz = h2(floor(float2(uv.x * W.x, y * W.y)) + fr * 1.37);
        float snowAmt = amzp_snow * 0.6 + trk * 0.8;
        col = mix(col, float3(nz), clamp(snowAmt * (0.35 + 0.65 * nz), 0.0, 1.0));
        float sl = 0.5 + 0.5 * cos(fract(y * W.y / lh) * 6.2831853);
        col *= 1.0 - amzp_scanlines * 0.45 * (1.0 - sl);
        float2 vc = amzLayerNorm() - 0.5;
        col *= 1.0 - amzp_vignette * smoothstep(0.25, 0.75, length(vc * float2(1.0, W.y / W.x) * 1.2));
        col *= seam;
        col = clamp(col, 0.0, 1.0);
        amzOutput = float4(col * a, a);
    }
    void amzRender() {
        nmMain();
        if (!(amzp_overdrawOn>0.5)) amzOutput *= amzTexture(0, amzScreenNorm()).a;
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
